#!/usr/bin/env python3
"""
check_max_len.py

Estimate an appropriate Transformer max_length when EACH LOG LINE is a separate example.

What it does:
- Splits LOG_SAMPLE into non-empty lines.
- Tokenizes each line (with special tokens) using a HF tokenizer.
- Reports token length distribution and truncation rate for candidate max_len values.
- Recommends the smallest candidate where >= target_keep fraction of LINES fit without truncation.

Run:
  python check_max_len.py
Optional:
  python check_max_len.py --model roberta-base
  python check_max_len.py --target_keep 0.99
  python check_max_len.py --candidates 64 96 128 160 192 224 256 320 384 512
"""

