def parse_args() -> argparse.Namespace:
    ap = argparse.ArgumentParser()
    ap.add_argument("--model", type=str, default="roberta-base", help="HF tokenizer/model name.")
    ap.add_argument(
        "--target_keep",
        type=float,
        default=0.95,
        help="Target fraction of LINES that should fit within truncation tolerance (0..1).",
    )
    ap.add_argument(
        "--trunc_tol",
        type=float,
        default=0.1,
        help=(
            "Per-line truncation tolerance as a fraction (0..1). "
            "Example: 0.10 means up to 10% of tokens may be dropped and the line is still counted as NOT truncated."
        ),
    )
    ap.add_argument(
        "--candidates",
        type=int,
        nargs="*",
        default=[64, 96, 128, 160, 192, 224, 256, 320, 384, 512],
        help="Candidate max_length values to evaluate.",
    )
    ap.add_argument(
        "--show_longest",
        type=int,
        default=3,
        help="Show N longest lines (by tokens) for sanity checking.",
    )
    return ap.parse_args()


def tokenize_line_lengths(tok, lines: List[str]) -> List[int]:
    enc = tok(
        lines,
        truncation=False,
        add_special_tokens=True,
        padding=False,
        return_attention_mask=False,
    )
    return [len(ids) for ids in enc["input_ids"]]


def percentile(sorted_vals: List[int], p: float) -> int:
    if not sorted_vals:
        return 0
    if p <= 0:
        return sorted_vals[0]
    if p >= 1:
        return sorted_vals[-1]
    import math
    k = math.ceil(p * len(sorted_vals))
    return sorted_vals[k - 1]


def is_effectively_truncated(total_tokens: int, max_len: int, trunc_tol: float) -> bool:
    """
    Returns True iff the amount dropped is > trunc_tol fraction of the original length.
    If total_tokens <= max_len => not truncated.
    """
    if total_tokens <= max_len:
        return False
    dropped = total_tokens - max_len
    dropped_frac = dropped / max(1, total_tokens)
    return dropped_frac > trunc_tol


def main() -> None:
    args = parse_args()

    if not (0.0 < args.target_keep <= 1.0):
        raise SystemExit("--target_keep must be in (0, 1].")
    if not (0.0 <= args.trunc_tol < 1.0):
        raise SystemExit("--trunc_tol must be in [0, 1).")

    tok = AutoTokenizer.from_pretrained(args.model)

    lines = [ln.strip("\r") for ln in LOG_SAMPLE.splitlines() if ln.strip("\r").strip()]
    if not lines:
        raise SystemExit("LOG_SAMPLE has no non-empty lines.")

    lengths = tokenize_line_lengths(tok, lines)
    n = len(lengths)
    lengths_sorted = sorted(lengths)

    min_len = lengths_sorted[0]
    max_len_observed = lengths_sorted[-1]
    mean_len = sum(lengths_sorted) / n

    p50 = percentile(lengths_sorted, 0.50)
    p90 = percentile(lengths_sorted, 0.90)
    p95 = percentile(lengths_sorted, 0.95)
    p99 = percentile(lengths_sorted, 0.99)

    print(f"Tokenizer model : {args.model}")
    print(f"Lines in sample : {n}")
    print(f"Token lengths   : min={min_len}  mean={mean_len:.1f}  max={max_len_observed}")
    print(f"Percentiles     : p50={p50}  p90={p90}  p95={p95}  p99={p99}")
    print(f"Trunc tolerance : {args.trunc_tol:.0%} (<= this per-line drop is treated as NOT truncated)\n")

    print("Candidate max_length impact (per-line, with truncation tolerance):")
    best_len = None
    for L in args.candidates:
        ok = 0
        bad = 0
        for t in lengths:
            if is_effectively_truncated(t, L, args.trunc_tol):
                bad += 1
            else:
                ok += 1
        ok_frac = ok / n
        flag = ""
        if best_len is None and ok_frac >= args.target_keep:
            best_len = L
            flag = "  <-- first meeting target_keep"
        print(
            f"  max_len={L:>4} | ok_lines={ok:>4}/{n:<4} | truncated_lines={bad:>4} | ok_frac={ok_frac:>6.2%}{flag}"
        )

    if best_len is None:
        # "Needed" is no longer a pure percentile when you allow partial truncation;
        # we can still give a useful hint: target percentile on (1-trunc_tol) length.
        # Conservative hint: need max_len >= (1 - trunc_tol) * p_target_length
        import math
        raw_needed = percentile(lengths_sorted, args.target_keep)
        approx_needed = math.ceil((1.0 - args.trunc_tol) * raw_needed)
        print(
            f"\nNo candidate met target_keep={args.target_keep:.0%} of LINES with trunc_tol={args.trunc_tol:.0%}.\n"
            f"Rough hint: try candidates around >= {approx_needed} tokens (conservative estimate)."
        )
    else:
        print(
            f"\nRecommended max_len (from candidates, target_keep={args.target_keep:.0%} lines, trunc_tol={args.trunc_tol:.0%}): {best_len}"
        )

    if args.show_longest > 0:
        idx_sorted = sorted(range(n), key=lambda i: lengths[i], reverse=True)
        k = min(args.show_longest, n)
        print(f"\nTop {k} longest lines (tokens):")
        for rank in range(k):
            i = idx_sorted[rank]
            preview = lines[i]
            if len(preview) > 200:
                preview = preview[:200] + "…"
            print(f"  #{rank+1}: tokens={lengths[i]:>4} | {preview}")

    if max_len_observed > 512:
        print(
            "\nNOTE: Some single lines exceed 512 tokens. "
            "With BERT/RoBERTa-base you MUST truncate those lines (or switch to long-context models)."
        )


if __name__ == "__main__":
    main()